const directorStyle=document.createElement('style');directorStyle.textContent='#characterDirector{position:fixed;inset:90px 15px auto auto;margin:0;width:310px;max-height:75vh;overflow:auto;z-index:900;background:#1b1e26;border:1px solid #7964b2}#characterDirector textarea{width:100%;box-sizing:border-box}#characterDirector button{margin:4px 3px 4px 0}#directorPlanActions{font-size:12px;line-height:1.5}';document.head.append(directorStyle);
