$('closeCharacterDirector').onclick=()=>{directorPicking=false;$('stage').style.cursor='';$('characterDirector').close()};$('directorPickPoint').onclick=()=>{if(!characterDirectorContext)return;directorPicking=true;$('stage').style.cursor='crosshair';$('directorStatus').textContent='Choose a scene in the timeline, then click the destination in the preview.'};
