$('directorMakePlan').onclick=async()=>{if(directorWorking)return;let request;try{request=directorRequest()}catch(e){return $('directorStatus').textContent=e.message}directorWorking=true;$('directorMakePlan').disabled=true;$('directorStatus').textContent='Planning on this PC…';const signature=JSON.stringify(project);try{const response=await fetch('/api/director/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)}),result=await response.json();if(!response.ok)throw Error(result.error||'The AI could not make a plan.');if(signature!==JSON.stringify(project))throw Error('The project changed. Make the plan again.');if(result.needsPoint&&!characterDirectorContext.destination)throw Error('Choose a destination point, then make the plan again.');characterDirectorPlan=planDirectedActions(result);$('directorPlanActions').replaceChildren();const summary=document.createElement('p');summary.textContent=result.summary;$('directorPlanActions').append(summary);for(const action of result.actions){const row=document.createElement('p');row.textContent=action.kind+' · '+action.duration+'s'+(action.text?' · '+action.text:'');$('directorPlanActions').append(row)}$('directorPreviewPlan').disabled=$('directorApplyPlan').disabled=false;$('directorStatus').textContent='Plan ready. The project has not changed.'}catch(e){$('directorStatus').textContent=e.message}finally{directorWorking=false;$('directorMakePlan').disabled=false}};
let directorPreviewRAF=0;function stopDirectorPreview(){cancelAnimationFrame(directorPreviewRAF);directorPreviewRAF=0;$('directorPreviewPlan').textContent='Preview movement'}
$('directorPreviewPlan').onclick=()=>{if(directorPreviewRAF)return stopDirectorPreview();const plan=characterDirectorPlan;if(!plan)return;let canvas=$('directorPreviewCanvas');if(!canvas){canvas=document.createElement('canvas');canvas.id='directorPreviewCanvas';canvas.width=640;canvas.height=360;$('directorPlanActions').append(canvas)}const started=performance.now();$('directorPreviewPlan').textContent='Stop preview';function frame(now){if(!$('characterDirector').open||characterDirectorPlan!==plan)return stopDirectorPreview();const at=Math.min(plan.end,plan.start+(now-started)/1000),before=project;try{project=plan.project;const owner=narrationSceneAt(project,Math.min(at,totalDuration()-.00001));renderSceneFrame(canvas.getContext('2d'),owner.scene,Math.max(0,at-owner.offset))}finally{project=before}if(at<plan.end)directorPreviewRAF=requestAnimationFrame(frame);else stopDirectorPreview()}directorPreviewRAF=requestAnimationFrame(frame)};
$('directorApplyPlan').onclick=async()=>{const plan=characterDirectorPlan;if(!plan)return;if(JSON.stringify(project)!==plan.signature)return $('directorStatus').textContent='The project changed. Make the plan again.';Object.assign(project,plan.project);sceneIndex=project.scenes.findIndex(s=>s.id===plan.sceneId);time=clamp(plan.end-storySceneOffset(current()),0,current().duration);selectLayers([plan.actorId]);save();render();$('directorStatus').textContent='Actions applied. Undo restores the previous version.';characterDirectorPlan=null;$('directorApplyPlan').disabled=true;const reply=plan.speech[0];if(reply){sceneIndex=project.scenes.findIndex(s=>s.id===reply.sceneId);const line=storyLines(current()).find(l=>l.id===reply.lineId);await openOfflineVoice(line)}};

const stateBeforeDirectedPoints=stateAt;stateAt=function(o,t){const v=stateBeforeDirectedPoints(o,t),point=(o.directedPoints||[]).find(p=>t>=p.start&&t<=p.start+p.duration);if(!point)return v;const solved=solveInteractionHand(characterAtView(o,t),v,'right',point),f=(t-point.start)/point.duration,w=Math.min(1,f*5,(1-f)*5);for(const key of ['rightArm','rightElbow'])if(Number.isFinite(solved[key]))v[key]+=(solved[key]-v[key])*w;v.handOpen=Math.max(v.handOpen,w);return v};
